package run.ikaros.planning; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.IfMatchVersion;
@RestController @RequestMapping("/api/v2/planning/comments") public class PlanningCommentController {private final PlanningCommentService s;public PlanningCommentController(PlanningCommentService s){this.s=s;} @PostMapping public Mono<PlanningCommentView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@Valid@RequestBody CreatePlanningCommentRequest r){return s.create(a,r);}@GetMapping public Flux<PlanningCommentView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@RequestParam PlanningCommentTargetType targetType,@RequestParam UUID targetId){return s.list(o,targetType,targetId);}@PatchMapping("/{commentId}")public Mono<ResponseEntity<PlanningCommentView>> update(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID commentId,@RequestHeader(value="If-Match",required=false)String ifMatch,@Valid@RequestBody UpdatePlanningCommentRequest r){long version=IfMatchVersion.parse(ifMatch);return s.update(a,commentId,new UpdatePlanningCommentRequest(r.content(),version)).map(view->ResponseEntity.ok().eTag(IfMatchVersion.etag(view.version())).body(view));}@DeleteMapping("/{commentId}")public Mono<Void> delete(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID commentId){return s.delete(a,commentId);}}
